export function ledgerFor(room: Room, details: Record<string, BoardQuestDetail>, threadId: string) {
  const quests: BoardQuestSummary[] = room.keepers.find((k) => k.member.threadId === threadId)?.boardQuests ?? [];
  const own = quests.map((q) => details[q.id]).filter((d): d is BoardQuestDetail => !!d);
  return ledgerSchema.parse({ keeperThreadId: threadId, boardQuests: quests, decisions: own.flatMap((d) => d.decisions), rules: own[0]?.rules ?? [], asks: own.flatMap((d) => d.asks), routes: own.flatMap((d) => d.routes), restatement: quests.length ? `You are ${threadId === "thr-moss" ? "Moss" : "Wren"}, Keeper of ${quests.length} board quests.\n${quests.map((q) => `${q.short} · plan v${q.planVersion} · ${q.phase}: ${q.move.text}`).join("\n")}\nRules: No docs-only PRs. Every PR on the envoy Shuttle board. Draft only; DNS cut needs an explicit go.` : "", lastReanchorAt: quests.length ? min(32) : null });
}

